import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as l,c as d,o as e,af as r,b as o,w as a,a as h,G as s,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"模型生命周期（桥接）","description":"模型生命周期组的导览——两条链在 Inference 汇合；组内四页（LLM 心智模型、模型架构、数据预训练与 Scaling、后训练）各自回答什么工程决策，训练数学与推导归 Learn LLM。","frontmatter":{"title":"模型生命周期（桥接）","description":"模型生命周期组的导览——两条链在 Inference 汇合；组内四页（LLM 心智模型、模型架构、数据预训练与 Scaling、后训练）各自回答什么工程决策，训练数学与推导归 Learn LLM。","domain":"tech","tags":["tech","orientation","bridge","model-lifecycle"],"navOrder":10,"topicId":"model-lifecycle-bridge","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/"}],"prerequisites":["site-boundaries"],"next":["llm-mental-model"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/index.md","filePath":"zh/tech/01-model-lifecycle/index.md","lastUpdated":1788429430000}'),p={name:"zh/tech/01-model-lifecycle/index.md"};function f(m,t,g,u,b,L){const n=l("Mermaid");return e(),d("div",null,[t[1]||(t[1]=r('<blockquote><p><strong>在哪一组</strong>：组 01 · 模型生命周期（桥接组）｜ <strong>上一组出口</strong>：能判断知识归属、并为需求选出最低复杂度方案（00-map 组） ｜ <strong>本组出口</strong>：能说出模型生命周期如何影响工程决策（何时 prompt 不够、模型怎么选、成本怎么算），并知道深层原理去 Learn LLM 哪一章 <strong>前置</strong>：<a href="./../00-map/site-boundaries.html">站点边界与知识 ownership</a> ｜ <strong>下一步</strong>：<a href="./llm-mental-model.html">LLM 心智模型（桥接）</a>；读完本组进 <a href="./../02-inference-interface/">02-inference-interface 组</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：模型生命周期（从数据、预训练、后训练到推理）必须在技术地图上有位置，否则你看不懂自己系统的上下游；但本仓只在它<strong>影响工程决策</strong>的深度上讲它——训练数学、实验细节与完整推导归 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。本组是桥接组：四页各桥一个概念域，正文只写「概念定位 → 为什么应用工程师需要知道 → 决策影响 → 链接 Learn LLM」，不复制推导。</p><h3 id="心智模型-两条链在-inference-汇合" tabindex="-1">心智模型：两条链在 Inference 汇合 <a class="header-anchor" href="#心智模型-两条链在-inference-汇合" aria-label="Permalink to &quot;心智模型：两条链在 Inference 汇合&quot;">​</a></h3>',4)),(e(),o(c,null,{default:a(()=>[s(n,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20A%20%5B%22%E6%A8%A1%E5%9E%8B%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E9%93%BE%20%E2%80%94%E2%80%94%20%E6%B7%B1%E5%B1%82%E5%8E%9F%E7%90%86%E5%BD%92%20Learn%20LLM%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22ML%20%2F%20DL%20%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20A2%5B%22LLM%20%E5%BF%83%E6%99%BA%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20%20%20%20%20%20%20A2%20--%3E%20A3%5B%22Data%20%2F%20Pretraining%20%2F%20Scaling%22%5D%0A%20%20%20%20%20%20%20%20A3%20--%3E%20A4%5B%22Post-training%EF%BC%9ASFT%20%C2%B7%20RLHF%20%C2%B7%20PEFT%22%5D%0A%20%20%20%20%20%20%20%20A4%20--%3E%20A5%5B%22Inference%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20B%20%5B%22AI%20%E7%B3%BB%E7%BB%9F%E5%B7%A5%E7%A8%8B%E9%93%BE%20%E2%80%94%E2%80%94%20%E6%9C%AC%E4%BB%93%20canonical%20%E4%B8%BB%E7%BA%BF%22%5D%0A%20%20%20%20%20%20%20%20B1%5B%22Inference%20%2F%20Model%20Interface%22%5D%20--%3E%20B2%5B%22Context%22%5D%0A%20%20%20%20%20%20%20%20B2%20--%3E%20B3%5B%22Grounding%20%2F%20RAG%22%5D%0A%20%20%20%20%20%20%20%20B3%20--%3E%20B4%5B%22Tools%20%2F%20Action%22%5D%0A%20%20%20%20%20%20%20%20B4%20--%3E%20B5%5B%22Agent%20Runtime%20%2F%20State%22%5D%0A%20%20%20%20%20%20%20%20B5%20--%3E%20B6%5B%22Interoperability%22%5D%0A%20%20%20%20%20%20%20%20B6%20--%3E%20B7%5B%22Production%20%2F%20Operations%22%5D%0A%20%20%20%20end%0A%20%20%20%20A5%20%3D%3D%3E%7C%E6%B1%87%E5%90%88%7C%20B1%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[h(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<p>你写的每一行 AI 应用代码，都从左链的末端（Inference）开始。左链决定「你手里这个模型是什么、会什么」；右链决定「你用它造什么」。两条链在 Inference / Model Interface 处汇合——这就是为什么下一组（02-inference-interface）的第一个主题是接口契约而不是模型结构。</p><h3 id="组内导航-4-页-按序读" tabindex="-1">组内导航（4 页，按序读） <a class="header-anchor" href="#组内导航-4-页-按序读" aria-label="Permalink to &quot;组内导航（4 页，按序读）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页</th><th>回答的问题</th><th>一句话结论</th></tr></thead><tbody><tr><td><a href="./llm-mental-model.html">LLM 心智模型</a></td><td>模型到底是什么</td><td>参数化条件概率模型：prompt 调用能力不注入知识、context 是硬约束、temperature 是采样参数</td></tr><tr><td><a href="./architecture.html">模型架构</a></td><td>架构术语如何变成账单</td><td>不必会推导，但要把 Attention / RoPE / MoE / KV cache 翻译成 context 长度与推理成本</td></tr><tr><td><a href="./data-pretraining-scaling.html">数据、预训练与 Scaling</a></td><td>模型的知识与上限从哪来</td><td>能力上限冻结于预训练：knowledge cutoff、定价档位、任务可靠性都源于这条链</td></tr><tr><td><a href="./post-training/">后训练</a>（子组三页）</td><td>何时值得动权重</td><td>SFT / RLHF / PEFT 的工程决策桥；先穷尽 prompt 与 RAG</td></tr></tbody></table><h3 id="关键术语-首现全称" tabindex="-1">关键术语（首现全称） <a class="header-anchor" href="#关键术语-首现全称" aria-label="Permalink to &quot;关键术语（首现全称）&quot;">​</a></h3><ul><li><strong>SFT</strong>（Supervised Fine-Tuning，监督微调）：用标注样本继续训练，改变模型行为。</li><li><strong>RLHF</strong>（Reinforcement Learning from Human Feedback，人类反馈强化学习）：用人类偏好信号训练奖励模型再优化策略。</li><li><strong>PEFT</strong>（Parameter-Efficient Fine-Tuning，参数高效微调）：只训练少量附加参数（如 LoRA）以降低训练成本。</li><li><strong>Scaling</strong>：模型规模、数据量与算力共同决定能力的经验规律。</li></ul><h2 id="_2-何时跳转" tabindex="-1">2. 何时跳转 <a class="header-anchor" href="#_2-何时跳转" aria-label="Permalink to &quot;2. 何时跳转&quot;">​</a></h2><p>本组无可运行产物；替代动作（约 5 分钟）：在总图上找到你关心的环节（例如「模型为什么不肯稳定输出 JSON」→ 左链 Post-training 与右链 Context 的交界），判断它是工程问题还是原理问题（工程问题走右链的本仓组，原理问题跳 Learn LLM），并记录停止点——本组正文到「生命周期塑造接口属性」为止。查单个问题时直接按表进：</p><table tabindex="0"><thead><tr><th>症状 / 问题</th><th>去哪</th></tr></thead><tbody><tr><td>模型「不知道」某事实、知识过时</td><td><a href="./data-pretraining-scaling.html">数据、预训练与 Scaling</a> → <a href="./../04-grounding/rag.html">RAG</a></td></tr><tr><td>账单 / 延迟与预期不符</td><td><a href="./architecture.html">模型架构</a> → <a href="./../08-production/cost-performance.html">成本与性能</a></td></tr><tr><td>输出格式不稳定</td><td><a href="./../02-inference-interface/structured-output.html">结构化输出</a>（接口契约问题，不是模型理解问题）</td></tr><tr><td>想真正理解训练与推理内部</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM 章节目录</a>（全书 21 章）</td></tr></tbody></table><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么左链必须在地图上、又不在本仓展开" tabindex="-1">为什么左链必须在地图上、又不在本仓展开 <a class="header-anchor" href="#为什么左链必须在地图上、又不在本仓展开" aria-label="Permalink to &quot;为什么左链必须在地图上、又不在本仓展开&quot;">​</a></h3><p><strong>必须在地图上</strong>：不懂「模型来自一条训练管线」的工程师会把所有问题都当成 prompt 问题——不知道 instruct 与 base 模型的行为差异来自后训练，不知道上下文预算来自推理期缓存结构，不知道模型版本升级可能改变一切工程假设。地图缺少左链，右链的每个「为什么」都悬空。</p><p><strong>不在本仓展开</strong>：训练数学、数据工程、实验方法是一个完整学科，Learn LLM 已按 21 章覆盖（retrievedAt 2026-09-01）。本仓复制任何一段推导都会制造第二 canonical 并随时间漂移（规则见<a href="./../00-map/site-boundaries.html">站点边界</a>）。</p><h3 id="汇合点的工程含义" tabindex="-1">汇合点的工程含义 <a class="header-anchor" href="#汇合点的工程含义" aria-label="Permalink to &quot;汇合点的工程含义&quot;">​</a></h3><p>Inference 是两条链唯一共享的节点，它把左链的全部历史（数据、规模、后训练）压缩成三个工程可见的接口属性：</p><ul><li><strong>行为</strong>：指令遵循、格式稳定性、拒答边界——接口契约（02-inference-interface 组）的直接约束对象。</li><li><strong>预算</strong>：上下文长度与缓存成本——上下文工程（03-context 组）与成本治理（08-production 组）的约束来源。</li><li><strong>能力边界</strong>：能做什么、不能做什么——工具与 Agent 设计（05-action、06-agent-systems 组）的输入假设。</li></ul><p>工程上你永远通过这三个属性消费模型，而不是通过其训练细节。这就是「模型是可替换的外部能力」这一主线设定的依据。</p><p><strong>规范要求 vs 本地实测</strong>：不适用——本组无协议规范；站点层面的「实测」是资源库中各 Learn LLM 章节 URL 的 200 状态（retrievedAt 2026-09-01）。</p><h2 id="_4-工程决策影响" tabindex="-1">4. 工程决策影响 <a class="header-anchor" href="#_4-工程决策影响" aria-label="Permalink to &quot;4. 工程决策影响&quot;">​</a></h2><h3 id="决策表-改行为还是加知识" tabindex="-1">决策表：改行为还是加知识 <a class="header-anchor" href="#决策表-改行为还是加知识" aria-label="Permalink to &quot;决策表：改行为还是加知识&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>方向</th><th>控制权</th><th>状态</th><th>信任域</th><th>最低复杂度</th></tr></thead><tbody><tr><td>提示词 + 上下文（prompt + context）</td><td>读，即时可改</td><td>每次调用可调整</td><td>无</td><td>进程内</td><td>最低——默认从这里开始</td></tr><tr><td>RAG（检索增强生成）</td><td>读，随数据更新</td><td>你控索引与刷新节奏</td><td>检索库</td><td>数据源边界</td><td>中</td></tr><tr><td>SFT / RLHF / PEFT</td><td>改模型本身</td><td>训练管线 + 权重版本管理</td><td>模型权重版本</td><td>模型供应链</td><td>最高——本仓不展开实现</td></tr></tbody></table><p><strong>经验法则（本仓立场，非量化断言）</strong>：绝大多数应用需求应先穷尽 prompt + 上下文，再考虑 RAG；只有当你需要<strong>改变模型的行为方式</strong>（而非补充事实）且拥有大量高质量标注数据、训练预算与相应工程能力时，才评估后训练。三者任一不具备，先回 RAG。旧版训练页中「10,000+ 样本 / $10,000+ 预算」等具体数字无一手来源，已删除，不作断言。</p><h3 id="生命周期影响哪三个工程决策" tabindex="-1">生命周期影响哪三个工程决策 <a class="header-anchor" href="#生命周期影响哪三个工程决策" aria-label="Permalink to &quot;生命周期影响哪三个工程决策&quot;">​</a></h3><ol><li><strong>何时 prompt 不够</strong>：知识缺失 → 先 RAG（04-grounding 组）；行为不符（语气、格式、拒绝策略）→ 调 prompt 与 few-shot；两者都穷尽且需求稳定 → 才讨论后训练（组内 <a href="./post-training/">post-training/</a>）。</li><li><strong>模型选择</strong>：base / instruct / 微调 / 量化版本在能力、成本、部署位置上差异巨大；量化与推理 runtime 的数学归 Learn LLM，选型决策框架归 02-inference-interface 组。</li><li><strong>成本结构</strong>：训练是一次性大额支出，推理与检索是持续变动支出；成本治理见 08-production 组，训练成本估算不在本仓展开。</li></ol><p>维护规则（替代 runbook）：当 Learn LLM 章节结构调整时，重新核验本组全部 deep-link 并更新各页 <code>lastVerified</code>；本仓侧新增与生命周期相关的工程决策主题（如模型版本升级策略）时，在对应组章节内展开，本导览只加一行指针。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><ul><li><strong>Beginner</strong>：本导览 + <a href="./llm-mental-model.html">LLM 心智模型</a>——能说出两条链、汇合点与一个正确的心智模型。</li><li><strong>Builder</strong>：进 <a href="./../02-inference-interface/">02-inference-interface 组</a>，从汇合点的工程侧开始动手——本组给判断，接口组给实现。</li><li><strong>Operator</strong>：关注模型版本升级对契约与成本的影响（08-production 组）——升级会改变本组全部假设。</li><li><strong>Researcher</strong>：沿下面的 Learn LLM 章节下沉到训练与推理原理——深层原理的唯一 canonical。</li></ul><h3 id="资源表-learn-llm-章节-均经章节目录核验-retrievedat-2026-09-01" tabindex="-1">资源表（Learn LLM 章节，均经章节目录核验，retrievedAt 2026-09-01） <a class="header-anchor" href="#资源表-learn-llm-章节-均经章节目录核验-retrievedat-2026-09-01" aria-label="Permalink to &quot;资源表（Learn LLM 章节，均经章节目录核验，retrievedAt 2026-09-01）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>canonical URL</th><th>对应本组环节</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>章节目录（全书 21 章地图）</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/</a></td><td>两条链的完整展开</td><td>深层原理归 Learn LLM</td><td>按环节选章</td></tr><tr><td>第 4 章 字符语言模型</td><td><a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/04-probabilistic-lm</a></td><td>LLM 心智模型</td><td>条件概率与采样是核心机制</td><td>组内<a href="./llm-mental-model.html">心智模型页</a></td></tr><tr><td>第 7 章 Transformer</td><td><a href="https://llm.zenheart.site/chapters/07-attention" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/07-attention</a></td><td>模型架构</td><td>Attention / causal mask / 多头的从零实现</td><td>组内<a href="./architecture.html">架构页</a></td></tr><tr><td>第 8 章 TinyGPT</td><td><a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/08-tinygpt</a></td><td>Data / Pretraining</td><td>预训练从零实现可见</td><td>组内<a href="./data-pretraining-scaling.html">数据预训练页</a></td></tr><tr><td>第 6 章 Training Stability</td><td><a href="https://llm.zenheart.site/chapters/06-training-stability" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/06-training-stability</a></td><td>预训练工程</td><td>训练稳定性是工程问题</td><td>—</td></tr><tr><td>第 10 章 Post-training</td><td><a href="https://llm.zenheart.site/chapters/10-post-training" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/10-post-training</a></td><td>SFT / RLHF / PEFT</td><td>后训练塑造行为与指令遵循</td><td>组内<a href="./post-training/">后训练子组</a></td></tr><tr><td>第 9 章 推理与量化</td><td><a href="https://llm.zenheart.site/chapters/09-inference-cache" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/09-inference-cache</a></td><td>汇合点：Inference</td><td>推理期缓存约束上下文预算</td><td><a href="./../03-context/">03-context 组</a></td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：如果你发现一个工程决策<strong>必须</strong>依赖训练细节才能做对（例如本地微调的显存估算），说明它属于组内后训练子组或 Learn LLM，而不是本导览——请把断言下沉到正确 owner，不要在此扩写。</li><li>未决：LoRA / QLoRA 选型影响的 owner 是组内 <a href="./post-training/peft.html">PEFT 页</a>；Learn LLM 章节深度链接以 2026-09-01 全量核验为基线，章节结构变化时随维护规则重验。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>训练目标与数学（SFT / DPO / LoRA 推导）：Learn LLM <a href="https://llm.zenheart.site/chapters/10-post-training" target="_blank" rel="noreferrer">第 10 章</a>——本仓到此为止。</li><li>用模型开始造东西：本仓 <a href="./../02-inference-interface/">02-inference-interface 组</a>与<a href="./../00-map/complexity-ladder.html">复杂度决策阶梯</a>。</li><li>证明效果可上线：<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>。</li></ul>',33))])}const P=i(p,[["render",f]]);export{x as __pageData,P as default};
